// Verify the Convex signature before trusting anything in the body.
// Replays older than five minutes are rejected.
const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set');
const item = $input.first().json;
const headers = item.headers || {};
const ts = String(headers['x-lendloop-timestamp'] || '');
const given = String(headers['x-lendloop-signature'] || '').replace(/^sha256=/, '');
const body = JSON.stringify(item.body);
const age = Math.abs(Date.now() / 1000 - Number(ts));
const expected = crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
const valid = Number.isFinite(age) && age <= 300 && given.length === expected.length
  && crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected));
return [{ json: { valid, event: item.body } }];

// The notification itself. Swap the mock for an Email, Slack or Discord node;
// the logged mock is the default so the workflow runs with no accounts.
// Only the fields the message needs are read, nothing else is forwarded.
//
// DELIVER AT MOST ONCE. Convex retries this webhook three times, and it
// answers 200 before this node runs, so a 200 only ever means "signature
// accepted". If the response is lost on the way back, Convex retries an event
// that was in fact delivered. The eventId is the dedupe key, so the SIDE
// EFFECT is guarded here, where it happens, rather than only at the write-back
// where it would be too late. Static data is per workflow and survives
// restarts; swap it for Redis or a database if this ever runs on more than one
// n8n instance.
const e = $input.first().json.event;

const store = $getWorkflowStaticData('global');
store.sent = store.sent || {};

// Keep the ledger bounded: an id older than a day cannot still be in flight.
const DAY = 86400000;
const now = Date.now();
for (const [id, at] of Object.entries(store.sent)) {
  if (now - at > DAY) delete store.sent[id];
}

if (store.sent[e.eventId]) {
  console.log(`[notify] duplicate ${e.eventId}, already delivered, not sending again`);
  return [{ json: { payload: { loanId: e.loanId, eventId: e.eventId, status: e.status, channel: 'log', duplicate: true } } }];
}

const lines = {
  requested: `${e.counterpart} asked to borrow your ${e.tool} from ${e.startDate} to ${e.endDate}.`,
  approved: `${e.counterpart} approved your request for the ${e.tool}, ${e.startDate} to ${e.endDate}.`,
  declined: `${e.counterpart} could not lend the ${e.tool} this time.`,
  returned: `The ${e.tool} was marked as returned. Thanks!`,
};
const message = lines[e.status] || `Update on the ${e.tool}: ${e.status}.`;
console.log(`[notify] to ${e.recipient.name} <${e.recipient.email}>: ${message}`);

// Recorded only after the send above succeeded.
store.sent[e.eventId] = now;

return [{ json: { payload: { loanId: e.loanId, eventId: e.eventId, status: e.status, channel: 'log' } } }];

// Sign an outgoing write-back for Convex. Secret from the container env,
// never from this file. Signature = HMAC-SHA256(secret, `${ts}.${body}`).
const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is not set');
return $input.all().map((item) => {
  const body = JSON.stringify(item.json.payload);
  const ts = String(Math.floor(Date.now() / 1000));
  const sig = crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
  return { json: { body, ts, sig: `sha256=${sig}` } };
});
